<?php
namespace App\Domain\Fiscal;
use App\Domain\Tenancy\CurrentOrganization;use App\Models\{FiscalDocument,FiscalDocumentTax,User};use Carbon\CarbonImmutable;use DomainException;use Illuminate\Support\Facades\DB;
final class FiscalTaxCompositionManager {public function __construct(private readonly CurrentOrganization $currentOrganization){}public function record(FiscalTaxCompositionData $data,User $actor):FiscalDocument{ $org=$this->organization($actor);if($data->components===[]){throw new DomainException('La composición tributaria requiere al menos un componente explícito.');}return DB::transaction(function()use($data,$org){$document=FiscalDocument::query()->forOrganization($org)->lockForUpdate()->find($data->fiscalDocumentId);if(!$document){throw new DomainException('El documento no pertenece a la organización activa.');}$existing=$document->taxComponents()->count();if($existing){throw new DomainException('El documento ya posee composición tributaria inmutable.');}foreach($data->components as $index=>$item){if(!is_array($item)||blank($item['tax_code']??null)||!isset($item['taxable_base_minor'],$item['rate_basis_points'],$item['tax_amount_minor'])){throw new DomainException('Cada componente tributario debe ser explícito y completo.');}FiscalDocumentTax::query()->create(['organization_id'=>$org,'fiscal_document_id'=>$document->id,'position'=>$index+1,'tax_code'=>$item['tax_code'],'taxable_base_minor'=>$item['taxable_base_minor'],'rate_basis_points'=>$item['rate_basis_points'],'tax_amount_minor'=>$item['tax_amount_minor'],'created_at'=>CarbonImmutable::now()]);}return $document->refresh()->load('taxComponents');},3);}private function organization(User $actor):int{$id=$this->currentOrganization->id($actor);if(!($this->currentOrganization->roleFor($actor)?->canManageOrganization()??false)){throw new DomainException('Sólo un administrador puede registrar composición tributaria.');}return $id;}}
